base.src/utils.ts:
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

export function formatDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/**
 * Where to send someone after they sign in. Only a path on this site is allowed:
 * a full URL, a protocol-relative `//host`, or a backslash trick all fall back to home.
 */
export function safeRedirect(target: string | null | undefined): string {
  if (!target) return '/';
  if (!target.startsWith('/') || target.startsWith('//')) return '/';
  if (target.includes('\\')) return '/';
  return target;
}

/** The `next` query parameter of a sign-in URL, made safe to redirect to. */
export function nextFrom(url: URL): string {
  return safeRedirect(url.searchParams.get('next'));
}

export function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n));
}

base.src/login.ts:
import { nextFrom } from './utils.ts';

export type Session = { userId: string };

/** After a successful sign-in, redirect to the page the user came from. */
export function afterSignIn(session: Session, requestUrl: string): Response {
  const location = nextFrom(new URL(requestUrl));
  return new Response(null, { status: 303, headers: { location, 'x-user': session.userId } });
}

base.test/redirect.test.ts:
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { safeRedirect } from '../src/utils.ts';

test('keeps a path on this site', () => {
  assert.equal(safeRedirect('/settings'), '/settings');
});

test('refuses a full URL', () => {
  assert.equal(safeRedirect('https://evil.example/'), '/');
});

